import unittest
from candidate import monotonic

class TestMonotonic(unittest.TestCase):
    def test_monotonic_increasing_list_return_true(self):
        self.assertTrue(monotonic([1, 2, 4, 20]))

    def test_monotonic_decreasing_list_return_true(self):
        self.assertTrue(monotonic([4, 1, 0, -10]))

    def test_monotonic_non_monotonic_list_return_false(self):
        self.assertFalse(monotonic([1, 20, 4, 10]))

    def test_monotonic_empty_list_return_true(self):
        self.assertTrue(monotonic([]))

    def test_monotonic_single_element_return_true(self):
        self.assertTrue(monotonic([5]))

    def test_monotonic_all_duplicates_return_true(self):
        self.assertTrue(monotonic([1, 1, 1]))

    def test_monotonic_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            monotonic(None)
